                )
            )
            (?:/
                {nested_paren_chunk}
            )?)
            | (?:[\w.-]+\@[\w.-]+\.[\w]+)
            {file_links}
            | (?:bitcoin:[13][a-km-zA-HJ-NP-Z1-9]{{25,34}})
        )
        (?=
            [!:;\?\),\.\'\"\>]*
            (?:\Z|\s)
        )
