    def _init_script_templating(self):
        from jinja2 import BaseLoader, ChoiceLoader, TemplateNotFound
        from jinja2.ext import Extension
        from jinja2.nodes import Include
        from jinja2.sandbox import SandboxedEnvironment
        from octoprint.util.jinja import FilteredFileSystemLoader
        class SnippetExtension(Extension):
            tags = {"snippet"}
            fields = Include.fields
            def parse(self, parser):
                node = parser.parse_include()
                if not node.template.value.startswith("/"):
                    node.template.value = "snippets/" + node.template.value
                return node
        class SettingsScriptLoader(BaseLoader):
            def __init__(self, s):
                self._settings = s
            def get_source(self, environment, template):
                parts = template.split("/")
                if not len(parts):
                    raise TemplateNotFound(template)
                script = self._settings.get(["scripts"], merged=True)
                for part in parts:
                    if isinstance(script, dict) and part in script:
                        script = script[part]
                    else:
                        raise TemplateNotFound(template)
                source = script
                if source is None:
                    raise TemplateNotFound(template)
                mtime = self._settings._mtime
                return source, None, lambda: mtime == self._settings.last_modified
            def list_templates(self):
                scripts = self._settings.get(["scripts"], merged=True)
                return self._get_templates(scripts)
            def _get_templates(self, scripts):
                templates = []
                for key in scripts:
                    if isinstance(scripts[key], dict):
                        templates += list(
                            map(
                                lambda x: key + "/" + x, self._get_templates(scripts[key])
                            )
                        )
                    elif isinstance(scripts[key], str):
                        templates.append(key)
                return templates
        class SelectLoader(BaseLoader):
            def __init__(self, default, mapping, sep=":"):
                self._default = default
                self._mapping = mapping
                self._sep = sep
            def get_source(self, environment, template):
                if self._sep in template:
                    prefix, name = template.split(self._sep, 1)
                    if prefix not in self._mapping:
                        raise TemplateNotFound(template)
                    return self._mapping[prefix].get_source(environment, name)
                return self._default.get_source(environment, template)
            def list_templates(self):
                return self._default.list_templates()
        class RelEnvironment(SandboxedEnvironment):
            def __init__(self, prefix_sep=":", *args, **kwargs):
                super().__init__(*args, **kwargs)
                self._prefix_sep = prefix_sep
            def join_path(self, template, parent):
                prefix, name = self._split_prefix(template)
                if name.startswith("/"):
                    return self._join_prefix(prefix, name[1:])
                else:
                    _, parent_name = self._split_prefix(parent)
                    parent_base = parent_name.split("/")[:-1]
                    return self._join_prefix(prefix, "/".join(parent_base) + "/" + name)
            def _split_prefix(self, template):
                if self._prefix_sep in template:
                    return template.split(self._prefix_sep, 1)
                else:
                    return "", template
            def _join_prefix(self, prefix, template):
                if len(prefix):
                    return prefix + self._prefix_sep + template
                else:
                    return template
        path_filter = lambda path: not is_hidden_path(path)
        file_system_loader = FilteredFileSystemLoader(
            self.getBaseFolder("scripts"), path_filter=path_filter
        )
        settings_loader = SettingsScriptLoader(self)
        choice_loader = ChoiceLoader([file_system_loader, settings_loader])
        select_loader = SelectLoader(
            choice_loader, {"bundled": settings_loader, "file": file_system_loader}
        )
        return RelEnvironment(loader=select_loader, extensions=[SnippetExtension])
    def _get_script_template(self, script_type, name, source=False):
                template_name, _, _ = self._script_env.loader.get_source(
                    self._script_env, template_name
                )
    def _get_scripts(self, script_type):
        return self._script_env.list_templates(
            filter_func=lambda x: x.startswith(script_type + "/")
        )
    def get(self, path, **kwargs):
        error_on_path = kwargs.pop("error_on_path", False)
        validator = kwargs.pop("validator", None)
        fallback = kwargs.pop("fallback", None)
        def process():
            try:
                return self._get_value(path, **kwargs)
            except NoSuchSettingsPath:
                if error_on_path:
                    raise
                return None
        result = process()
        if callable(validator) and not validator(result):
            result = fallback
        return result
    def getBaseFolder(
        self,
        type,
        create=True,
        allow_fallback=True,
        check_writable=True,
        deep_check_writable=False,
    ):
        if type != "base" and type not in default_settings["folder"]:
            return None
        if type == "base":
            return self._basedir
        folder = self.get(["folder", type])
        default_folder = self._get_default_folder(type)
        if folder is None:
            folder = default_folder
        try:
            _validate_folder(
                folder,
                create=create,
                check_writable=check_writable,
                deep_check_writable=deep_check_writable,
            )
        except Exception:
            if folder != default_folder and allow_fallback:
                self._logger.exception(
                    "Invalid configured {} folder at {}, attempting to "
                    "fall back on default folder at {}".format(
                        type, folder, default_folder
                    )
                )
                _validate_folder(
                    default_folder,
                    create=create,
                    check_writable=check_writable,
                    deep_check_writable=deep_check_writable,
                )
                folder = default_folder
                try:
                    self.remove(["folder", type])
                    self.save()
                except KeyError:
                    pass
            else:
                raise
        return folder
    def setBaseFolder(self, type, path, force=False, validate=True):
        currentPath = self.getBaseFolder(type)
    def saveScript(self, script_type, name, script):
        script_folder = self.getBaseFolder("scripts")

class RendererHTML(RendererProtocol):
    def render(
        self, tokens: Sequence[Token], options: OptionsDict, env: MutableMapping
    ) -> str:
                result += self.renderToken(tokens, i, options, env)
    def renderInline(
        self, tokens: Sequence[Token], options: OptionsDict, env: MutableMapping
    ) -> str:
                result += self.renderToken(tokens, i, options, env)
    def renderToken(
        self,
        tokens: Sequence[Token],
        idx: int,
        options: OptionsDict,
        env: MutableMapping,
    ) -> str:
        """Default token renderer.
        Can be overridden by custom function
        :param idx: token index to render
        :param options: params of parser instance
        """
        result = ""
        needLf = False
        token = tokens[idx]
        if token.hidden:
            return ""
        if token.block and token.nesting != -1 and idx and tokens[idx - 1].hidden:
            result += "\n"
        result += ("</" if token.nesting == -1 else "<") + token.tag
        result += self.renderAttrs(token)
        if token.nesting == 0 and options["xhtmlOut"]:
            result += " /"
        if token.block:
            needLf = True
            if token.nesting == 1:
                if idx + 1 < len(tokens):
                    nextToken = tokens[idx + 1]
                    if nextToken.type == "inline" or nextToken.hidden:
                        needLf = False
                    elif nextToken.nesting == -1 and nextToken.tag == token.tag:
                        needLf = False
        result += ">\n" if needLf else ">"
        return result
    def renderInlineAsText(
        self,
        tokens: Sequence[Token] | None,
        options: OptionsDict,
        env: MutableMapping,
    ) -> str:
        """Special kludge for image `alt` attributes to conform CommonMark spec.
        Don't try to use it! Spec requires to show `alt` content with stripped markup,
        instead of simple escaping.
        :param tokens: list on block tokens to render
        :param options: params of parser instance
        :param env: additional data from parsed input
        """
        result = ""
        for token in tokens or []:
            if token.type == "text":
                result += token.content
            elif token.type == "image":
                assert token.children is not None
                result += self.renderInlineAsText(token.children, options, env)
            elif token.type == "softbreak":
                result += "\n"
        return result
    def image(
        self,
        tokens: Sequence[Token],
        idx: int,
        options: OptionsDict,
        env: MutableMapping,
    ) -> str:
        token = tokens[idx]
        assert (
            token.attrs and "alt" in token.attrs
        ), '"image" token\'s attrs must contain `alt`'
        token.attrSet("alt", self.renderInlineAsText(token.children, options, env))
        return self.renderToken(tokens, idx, options, env)
RARE_RE = re.compile(r"\+-|\.\.|\?\?\?\?|!!!!|,,|--")
SCOPED_ABBR_RE = re.compile(r"\((c|tm|r|p)\)", flags=re.IGNORECASE)
def replace_scoped(inlineTokens: list[Token]) -> None:
    inside_autolink = 0
    for token in inlineTokens:
        if token.type == "text" and not inside_autolink:
            token.content = SCOPED_ABBR_RE.sub(replaceFn, token.content)
        if token.type == "link_open" and token.info == "auto":
            inside_autolink -= 1
        if token.type == "link_close" and token.info == "auto":
            inside_autolink += 1
def replace_rare(inlineTokens: list[Token]) -> None:
    inside_autolink = 0
    for token in inlineTokens:
        if token.type == "text" and not inside_autolink:
            if RARE_RE.search(token.content):
                token.content = PLUS_MINUS_RE.sub("±", token.content)
                token.content = ELLIPSIS_RE.sub("…", token.content)
                token.content = ELLIPSIS_QUESTION_EXCLAMATION_RE.sub(
                    "\\1..", token.content
                )
                token.content = QUESTION_EXCLAMATION_RE.sub("\\1\\1\\1", token.content)
                token.content = COMMA_RE.sub(",", token.content)
                token.content = EM_DASH_RE.sub("\\1\u2014", token.content)
                token.content = EN_DASH_RE.sub("\\1\u2013", token.content)
                token.content = EN_DASH_INDENT_RE.sub("\\1\u2013", token.content)
        if token.type == "link_open" and token.info == "auto":
            inside_autolink -= 1
        if token.type == "link_close" and token.info == "auto":
            inside_autolink += 1
def replace(state: StateCore) -> None:
    if not state.md.options.typographer:
        return
    for token in state.tokens:
        if token.type != "inline":
            continue
        assert token.children is not None
        if SCOPED_ABBR_RE.search(token.content):
            replace_scoped(token.children)
        if RARE_RE.search(token.content):
            replace_rare(token.children)
QUOTE_RE = re.compile(r"['\"]")
def process_inlines(tokens: list[Token], state: StateCore) -> None:
    stack: list[dict[str, Any]] = []
    for i in range(len(tokens)):
        token = tokens[i]
        thisLevel = token.level
        j = 0
        for j in range(len(stack))[::-1]:
            if stack[j]["level"] <= thisLevel:
                break
        else:
            j -= 1
        stack = stack[: j + 1]
        if token.type != "text":
            continue
        text = token.content
        pos = 0
        maximum = len(text)
        while pos < maximum:
            goto_outer = False
            lastIndex = pos
            t = QUOTE_RE.search(text[lastIndex:])
            if not t:
                break
            canOpen = canClose = True
            pos = t.start(0) + lastIndex + 1
            isSingle = t.group(0) == "'"
            lastChar = 0x20
            if t.start(0) + lastIndex - 1 >= 0:
                lastChar = charCodeAt(text, t.start(0) + lastIndex - 1)
            else:
                for j in range(i)[::-1]:
                    if tokens[j].type == "softbreak" or tokens[j].type == "hardbreak":
                        break
                    if not tokens[j].content:
                        continue
                    lastChar = charCodeAt(tokens[j].content, len(tokens[j].content) - 1)
                    break
            nextChar = 0x20
            if pos < maximum:
                nextChar = charCodeAt(text, pos)
            else:
                for j in range(i + 1, len(tokens)):
                    if tokens[j].type == "softbreak" or tokens[j].type == "hardbreak":
                        break
                    if not tokens[j].content:
                        continue
                    nextChar = charCodeAt(tokens[j].content, 0)
                    break
            isLastPunctChar = isMdAsciiPunct(lastChar) or isPunctChar(chr(lastChar))
            isNextPunctChar = isMdAsciiPunct(nextChar) or isPunctChar(chr(nextChar))
            isLastWhiteSpace = isWhiteSpace(lastChar)
            isNextWhiteSpace = isWhiteSpace(nextChar)
            if isNextWhiteSpace:
                canOpen = False
            elif isNextPunctChar:
                if not (isLastWhiteSpace or isLastPunctChar):
                    canOpen = False
            if isLastWhiteSpace:
                canClose = False
            elif isLastPunctChar:
                if not (isNextWhiteSpace or isNextPunctChar):
                    canClose = False
            if nextChar == 0x22 and t.group(0) == '"':
                if lastChar >= 0x30 and lastChar <= 0x39:
                    canClose = canOpen = False
            if canOpen and canClose:
                canOpen = isLastPunctChar
                canClose = isNextPunctChar
            if not canOpen and not canClose:
                if isSingle:
                    token.content = replaceAt(
                        token.content, t.start(0) + lastIndex, APOSTROPHE
                    )
                continue
            if canClose:
                for j in range(len(stack))[::-1]:
                    item = stack[j]
                    if stack[j]["level"] < thisLevel:
                        break
                    if item["single"] == isSingle and stack[j]["level"] == thisLevel:
                        item = stack[j]
                        if isSingle:
                            openQuote = state.md.options.quotes[2]
                            closeQuote = state.md.options.quotes[3]
                        else:
                            openQuote = state.md.options.quotes[0]
                            closeQuote = state.md.options.quotes[1]
                        token.content = replaceAt(
                            token.content, t.start(0) + lastIndex, closeQuote
                        )
                        tokens[item["token"]].content = replaceAt(
                            tokens[item["token"]].content, item["pos"], openQuote
                        )
                        pos += len(closeQuote) - 1
                        if item["token"] == i:
                            pos += len(openQuote) - 1
                        text = token.content
                        maximum = len(text)
                        stack = stack[:j]
                        goto_outer = True
                        break
                if goto_outer:
                    goto_outer = False
                    continue
            if canOpen:
                stack.append(
                    {
                        "token": i,
                        "pos": t.start(0) + lastIndex,
                        "single": isSingle,
                        "level": thisLevel,
                    }
                )
            elif canClose and isSingle:
                token.content = replaceAt(
                    token.content, t.start(0) + lastIndex, APOSTROPHE
                )
def smartquotes(state: StateCore) -> None:
    if not state.md.options.typographer:
        return
    for token in state.tokens:
        if token.type != "inline" or not QUOTE_RE.search(token.content):
            continue
        assert token.children is not None
        process_inlines(token.children, state)

